190	    /**
191	     * The overall tax rate that actually ended up on the invoice: the sales tax as a percentage of the
192	     * total before tax, to two decimal places. It is below the headline rates when some
193	     * lines are tax-free, and zero when there is nothing before tax to charge it on.
194	     */
195	    public BigDecimal getEffectiveTaxPct() {
196	        BigDecimal totalExTax = getTotalExTax();
197	        if (totalExTax.signum() == 0) {
198	            return BigDecimal.ZERO.setScale(2);
199	        }
200	        return getTax().multiply(BigDecimal.valueOf(100)).divide(totalExTax, 2, RoundingMode.HALF_UP);
201	    }
