208	    /**
209	     * The percentages taken off the subtotal, added up (never more than 100); zero when there is no
210	     * percentage discount.
211	     */
212	    public BigDecimal getDiscountPct() {
213	        return discounts.stream().map(InvoiceDiscount::getDiscountPct).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add)
214	                .min(BigDecimal.valueOf(100).setScale(2));
215	    }
