357	/**
358	 * Lifecycle stage of an invoice: DRAFT -> SENT -> PARTIAL -> PAID. Once sent, the stage is worked
359	 * out from the payments and credit notes recorded against the invoice. A sent invoice with nothing paid against it can
360	 * instead be cancelled, making it VOID: it stays on record but is no longer owed. A sent or part-paid invoice that
361	 * will never be paid can be written off as bad debt, making it WRITTEN_OFF: likewise kept on record but no longer owed.
362	 */
363	public enum InvoiceStatus {
364	    DRAFT,
365	    SENT,
366	    PARTIAL,
367	    PAID,
368	    VOID,
369	    WRITTEN_OFF;
370	
371	    /** Whether payments can still be recorded against an invoice at this stage. */
372	    public boolean isOwing() {
373	        return this == SENT || this == PARTIAL;
374	    }
375	
376	    /** Whether an invoice at this stage is closed without being paid (cancelled or written off), so nothing is owed. */
377	    public boolean isClosedUnpaid() {
378	        return this == VOID || this == WRITTEN_OFF;
379	    }
380	}

