281	/** The one discount on an invoice: either a percentage or a flat amount taken off its subtotal, never both. */
282	@Entity
283	@Table(name = "invoice_discount")
284	public class InvoiceDiscount {
285	
286	    @Id
287	    @GeneratedValue(strategy = GenerationType.IDENTITY)
288	    private Long id;
289	
290	    @ManyToOne(fetch = FetchType.LAZY, optional = false)
291	    @JoinColumn(name = "invoice_id", nullable = false)
292	    private Invoice invoice;
