295	    private BigDecimal discountPct = BigDecimal.ZERO.setScale(2);
296	
297	    @Column(name = "discount_amount", nullable = false, precision = 12, scale = 2)
298	    private BigDecimal discountAmount = BigDecimal.ZERO.setScale(2);
299	
300	    /** The most a percentage discount takes off; null when it is not capped. */
301	    @Column(name = "discount_cap", precision = 12, scale = 2)
302	    private BigDecimal discountCap;
303	
304	    protected InvoiceDiscount() {
305	    }
306	
307	    InvoiceDiscount(Invoice invoice, BigDecimal discountPct, BigDecimal discountAmount) {
308	        this(invoice, discountPct, discountAmount, null);
309	    }
310	
311	    InvoiceDiscount(Invoice invoice, BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
312	        if (discountPct.signum() != 0 && discountAmount.signum() != 0) {
313	            throw new IllegalArgumentException("A discount is either a percentage or a flat amount, not both");
314	        }
315	        if (discountCap != null && discountPct.signum() == 0) {
316	            throw new IllegalArgumentException("Only a percentage discount can be capped");
317	        }
318	        this.invoice = invoice;
319	        this.discountPct = discountPct.setScale(2, RoundingMode.HALF_UP);
320	        this.discountAmount = discountAmount.setScale(2, RoundingMode.HALF_UP);
321	        this.discountCap = discountCap == null ? null : discountCap.setScale(2, RoundingMode.HALF_UP);
322	    }
323	
324	    /** Takes on the kind and size of another discount, keeping this one's place on the invoice. */
325	    void replaceWith(InvoiceDiscount other) {
326	        this.discountPct = other.discountPct;
327	        this.discountAmount = other.discountAmount;
328	        this.discountCap = other.discountCap;
329	    }
