503	   503	    /**
504	   504	     * Sets this invoice's one discount, either a percentage (optionally capped at the most it takes off) or
505	   505	     * a flat amount, replacing any it had (zero for both leaves no discount), and reworks its amount to match.
506	   506	     */
507	   507	    public void applyDiscount(BigDecimal discountPct, BigDecimal discountAmount, BigDecimal discountCap) {
508	   508	        InvoiceDiscount discount = new InvoiceDiscount(this, discountPct, discountAmount, discountCap);
509	   509	        if (discountPct.signum() == 0 && discountAmount.signum() == 0) {
510	   510	            discounts.clear();
511	   511	        } else if (discounts.isEmpty()) {
512	   512	            discounts.add(discount);
513	   513	        } else {
514	   514	            // The existing discount is changed in place, as an invoice only ever has the one.
515	   515	            discounts.get(0).replaceWith(discount);
516	   516	        }
517	   517	        recalculateAmount();
518	   518	    }
