615	   615	    /**
616	   616	     * Sets the early-payment discount offered on this invoice: the percentage taken off what is owed if it is
617	   617	     * paid within its client's early-payment window. It does not change the amount owed.
618	   618	     */
619	   619	    public void applyEarlyPayment(BigDecimal earlyPaymentPct) {
620	   620	        this.earlyPaymentPct = earlyPaymentPct.setScale(2, RoundingMode.HALF_UP);
621	   621	    }
622	   622	
623	   623	    /**
624	   624	     * Sets the settlement rebate offered on this invoice: the percentage of the amount given back if it is
625	   625	     * paid before the due date. It does not change the amount invoiced.
626	   626	     */
627	   627	    public void applyRebate(BigDecimal rebatePct) {
628	   628	        this.rebatePct = rebatePct.setScale(2, RoundingMode.HALF_UP);
629	   629	    }
630	   630	
631	   631	    /**
632	   632	     * The discount taken off one line, to the cent: the uncapped percentages together, plus its share of
633	   633	     * what the flat amounts and the capped percentages take off in proportion to what the line charges
634	   634	     * out of the subtotal.
635	   635	     */
636	   636	    private BigDecimal discountOn(BigDecimal line) {
637	   637	        BigDecimal subtotal = getSubtotal();
638	   638	        BigDecimal pct = percentOf(line, uncappedPct(subtotal));
639	   639	        if (subtotal.signum() == 0) {
640	   640	            return pct;
641	   641	        }
642	   642	        BigDecimal flatShare = sharedDiscount(subtotal).multiply(line).divide(subtotal, 2, RoundingMode.HALF_UP);
643	   643	        return pct.add(flatShare);
644	   644	    }
645	   645	
646	   646	    /** The percentages not limited by a cap, added up (never more than 100). */
647	   647	    private BigDecimal uncappedPct(BigDecimal subtotal) {
648	   648	        return discounts.stream().filter(d -> d.isPercentage() && !isCappedAt(subtotal, d)).map(InvoiceDiscount::getDiscountPct)
649	   649	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).min(BigDecimal.valueOf(100).setScale(2));
650	   650	    }
651	   651	
652	   652	    /**
653	   653	     * What the flat discounts and the capped percentages actually take off the subtotal together, shared
654	   654	     * across the lines in proportion to what each charges.
655	   655	     */
656	   656	    private BigDecimal sharedDiscount(BigDecimal subtotal) {
657	   657	        return discounts.stream().filter(d -> !d.isPercentage() || isCappedAt(subtotal, d)).map(this::discountTakenBy)
658	   658	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
659	   659	    }
660	   660	
661	   661	    /** The sales tax on one discounted taxable line (or inside it, when tax-inclusive), to the cent. */
662	   662	    private BigDecimal taxOn(BigDecimal line) {
663	   663	        return taxInclusive ? includedIn(line, taxPct) : percentOf(line, taxPct);
664	   664	    }
665	   665	
666	   666	    private static BigDecimal percentOf(BigDecimal base, BigDecimal pct) {
667	   667	        return base.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
668	   668	    }
