715	   715	    public String getPoNumber() {
716	   716	        return poNumber;
717	   717	    }
718	   718	
719	   719	    public void setPoNumber(String poNumber) {
720	   720	        this.poNumber = poNumber;
721	   721	    }
722	   722	
723	   723	    /**
724	   724	     * What is left to pay on this invoice given the totals paid and credited against it, less any part written
725	   725	     * off and any settlement rebate earned; nothing once it is void or written off.
726	   726	     */
727	   727	    public BigDecimal amountDue(BigDecimal paid, BigDecimal credited) {
728	   728	        return status.isClosedUnpaid() ? BigDecimal.ZERO.setScale(2)
729	   729	                : amount.subtract(paid).subtract(credited).subtract(writeOffAmount).subtract(rebateTaken);
730	   730	    }
731	   731	
732	   732	    /**
733	   733	     * What the client owes on this invoice right now given the totals paid and credited against it: what is
734	   734	     * left to pay less the retention still held back, never below nothing on account of the retention.
735	   735	     */
736	   736	    public BigDecimal dueNow(BigDecimal paid, BigDecimal credited) {
737	   737	        BigDecimal left = amountDue(paid, credited);
738	   738	        if (left.signum() <= 0 || status.isClosedUnpaid()) {
739	   739	            return left;
740	   740	        }
741	   741	        return left.subtract(getRetention()).max(BigDecimal.ZERO.setScale(2));
742	   742	    }
743	   743	
744	   744	    /**
745	   745	     * This invoice's status given the totals paid and credited against it. Once sent, it is PAID when the
746	   746	     * payments, credit notes, any part written off and any settlement rebate earned together clear the amount, PARTIAL once something has been
747	   747	     * paid, credited or written off, otherwise still SENT. Drafts, void and written-off invoices keep their status, as does one marked paid by hand.
748	   748	     */
749	   749	    public InvoiceStatus statusFor(BigDecimal paid, BigDecimal credited) {
750	   750	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
751	   751	            return status;
752	   752	        }
753	   753	        BigDecimal settled = paid.add(credited).add(writeOffAmount).add(rebateTaken);
754	   754	        if (settled.compareTo(amount) >= 0 || (status == InvoiceStatus.PAID && settled.signum() == 0)) {
755	   755	            return InvoiceStatus.PAID;
756	   756	        }
757	   757	        return settled.signum() > 0 ? InvoiceStatus.PARTIAL : InvoiceStatus.SENT;
758	   758	    }
759	   759	
760	   760	    /**
761	   761	     * Works out this sent invoice's status from what is still owed on it after the totals paid and credited against
762	   762	     * it and any part written off: PAID once nothing is left, PARTIAL once something has been settled, otherwise
763	   763	     * still SENT.
764	   764	     */
765	   765	    public void applySettledTotals(BigDecimal paid, BigDecimal credited) {
766	   766	        if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
767	   767	            throw new IllegalStateException("A " + status.name().toLowerCase() + " invoice cannot be settled");
768	   768	        }
769	   769	        this.status = statusFor(paid, credited);
770	   770	    }
771	   771	}
