296	    /**
297	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
298	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
299	     * when it was paid in. Each amount is rounded by the rule of the currency it is in, as the invoice is, so the
300	     * balances add up to the cent.
301	     */
302	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found, Function<String, MoneyRule> rules) {
303	        MoneyRule clientRule = clients.findById(clientId).map(c -> rules.apply(c.getCurrency())).orElse(MoneyRule.CENTS);
304	        Map<Long, MoneyRule> invoiceRules = new HashMap<>();
305	        found.forEach(i -> invoiceRules.put(i.getId(), rules.apply(i.getCurrency())));
306	        List<StatementEntry> entries = new ArrayList<>();
307	        List<Long> sent = new ArrayList<>();
308	        Map<Long, String> poNumbers = new HashMap<>();
309	        for (Invoice invoice : found) {
310	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
311	                continue;
312	            }
313	            sent.add(invoice.getId());
314	            if (invoice.getPoNumber() != null) {
315	                poNumbers.put(invoice.getId(), invoice.getPoNumber());
316	            }
317	            if (invoice.getStatus() != InvoiceStatus.VOID) {
318	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
319	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoiceRules.get(invoice.getId()).round(invoice.getAmount()),
320	                        invoice.getPoNumber()));
321	            }
322	        }
323	        if (!sent.isEmpty()) {
324	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
325	                if (payment.getDepositApplicationId() == null) {
326	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
327	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(),
328	                            invoiceRules.get(payment.getInvoiceId()).round(payment.getAmount()),
329	                            poNumbers.get(payment.getInvoiceId())));
330	                }
331	            }
332	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
333	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
334	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
335	                        "Credit note on invoice #" + note.getInvoiceId(),
336	                        invoiceRules.get(note.getInvoiceId()).round(note.getAmount()),
337	                        poNumbers.get(note.getInvoiceId())));
338	            }
339	        }
340	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
341	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
342	                    "Deposit", clientRule.round(deposit.getAmount()), null));
343	        }
344	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
345	            entries.add(StatementEntry.charge(StatementEntry.Kind.REFUND, refund.getId(), null, refund.getDate(),
346	                    "Refund", clientRule.round(refund.getAmount()), null));
347	        }
348	        return entries;
349	    }
