 69	    /**
 70	     * Records a payment against an invoice that has been sent to the client and is still owing, and
 71	     * works out the invoice's status from what has now been paid and credited. A payment may not take
 72	     * the total paid and credited beyond the invoice amount. A payment made in another currency is
 73	     * converted into the invoice's currency at the rates in effect on the payment's date, and settles
 74	     * that much of the invoice.
 75	     */
 76	    @Transactional
 77	    public PaymentResponse record(Long projectId, Long invoiceId, PaymentRequest request) {
 78	        Invoice invoice = find(projectId, invoiceId);
 79	        String currency = request.currency() == null ? invoice.getCurrency()
 80	                : request.currency().trim().toUpperCase(Locale.ROOT);
 81	        if (currency.equals(invoice.getCurrency())) {
 82	            return apply(invoice, request.amount(),
 83	                    () -> new Payment(invoice.getId(), request.amount(), request.date()));
 84	        }
 85	        if (!currencies.exists(currency)) {
 86	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
 87	        }
 88	        BigDecimal settles = fxRates.convert(currency, invoice.getCurrency(), request.date(), request.amount())
 89	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
 90	                        "No exchange rate for " + currency + " to " + invoice.getCurrency() + " on " + request.date()));
 91	        if (settles.signum() <= 0) {
 92	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The payment is too small to pay anything");
 93	        }
 94	        return apply(invoice, settles, () -> Payment.inForeignCurrency(invoice.getId(), settles, request.date(),
 95	                currency, request.amount()));
 96	    }
