131	    /**
132	     * Records one lump payment from a client split across several of their owing invoices. With
133	     * {@code useCredit} the client's credit is used up first (held deposits, then unused credit
134	     * notes) and the money received covers the rest; otherwise the money received covers it all.
135	     * The shares may not add up to more than the money received plus any credit used, and whatever
136	     * of the money received is left over is kept as credit for the client, so the money received
137	     * plus the credit used always equals the shares plus what is kept. Each invoice may appear
138	     * once, and each share is recorded as a payment against its own invoice under the same rules
139	     * as a payment made on its own. The lump and its shares are in the client's currency; a share
140	     * against an invoice in another currency is converted into the invoice's currency at the rates
141	     * in effect on the payment's date, so it settles the right amount of that invoice.
142	     */
143	    @Transactional
144	    public ClientPaymentResponse recordForClient(Long clientId, ClientPaymentRequest request) {
145	        String currency = clients.findById(clientId)
146	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"))
147	                .getCurrency();
148	        BigDecimal allocated = total(request.allocations(), ClientPaymentRequest.Allocation::amount).setScale(2);
149	        BigDecimal received = request.amount().setScale(2);
150	        BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);
151	        BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);
152	        if (request.usesCredit()) {
153	            ClientCreditResponse available = credit.available(clientId);
154	            fromDeposits = allocated.min(available.deposits());
155	            fromCreditNotes = allocated.subtract(fromDeposits).min(available.creditNotes());
156	        }
157	        BigDecimal fromReceived = allocated.subtract(fromDeposits).subtract(fromCreditNotes);
158	        if (fromReceived.compareTo(received) > 0) {
159	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, request.usesCredit()
160	                    ? "The shares add up to more than the payment and the credit available"
161	                    : "The shares add up to more than the payment");
162	        }
163	        BigDecimal toCredit = received.subtract(fromReceived);
164	        requireDistinct(request.allocations(), ClientPaymentRequest.Allocation::invoiceId);
165	        ClientPayment lump = clientPayments.saveAndFlush(new ClientPayment(clientId, received, request.date(),
166	                fromDeposits, fromCreditNotes, toCredit));
167	        List<PaymentResponse> shares = request.allocations().stream()
168	                .map(a -> {
169	                    Invoice invoice = findForClient(clientId, a.invoiceId());
170	                    BigDecimal settles = settles(currency, invoice, request.date(), a.amount());
171	                    return apply(invoice, settles,
172	                            () -> new Payment(a.invoiceId(), settles, request.date(), lump.getId(), a.amount()));
173	                })
174	                .toList();
175	        audit.record("CLIENT_PAYMENT_RECORDED id=" + lump.getId() + " client=" + clientId
176	                + " amount=" + lump.getAmount().toPlainString()
177	                + " fromDeposits=" + lump.getFromDeposits().toPlainString()
178	                + " fromCreditNotes=" + lump.getFromCreditNotes().toPlainString()
179	                + " toCredit=" + lump.getToCredit().toPlainString());
180	        return ClientPaymentResponse.from(lump, shares);
181	    }
