183	    /**
184	     * Puts part of a client's held deposits toward several of their owing invoices, today. The
185	     * shares may not add up to more than is still held, each invoice may appear once, and each share
186	     * is recorded as a payment against its own invoice under the same rules as a lump payment's,
187	     * converted into the invoice's currency at today's rates when it differs from the client's.
188	     */
189	    @Transactional
190	    public DepositApplicationResponse applyDeposits(Long clientId, DepositApplicationRequest request) {
191	        requireClient(clientId);
192	        BigDecimal allocated = total(request.allocations(), DepositApplicationRequest.Allocation::amount);
193	        BigDecimal held = credit.heldDeposits(clientId);
194	        if (allocated.compareTo(held) > 0) {
195	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
196	                    "The shares add up to more than the deposits held");
197	        }
198	        requireDistinct(request.allocations(), DepositApplicationRequest.Allocation::invoiceId);
199	        LocalDate today = LocalDate.now(clock);
200	        DepositApplication application = depositApplications.saveAndFlush(
201	                new DepositApplication(clientId, allocated, today));
202	        String currency = clients.findById(clientId).orElseThrow().getCurrency();
203	        List<PaymentResponse> shares = request.allocations().stream()
204	                .map(a -> {
205	                    Invoice invoice = findForClient(clientId, a.invoiceId());
206	                    BigDecimal settles = settles(currency, invoice, today, a.amount());
207	                    return apply(invoice, settles,
208	                            () -> Payment.fromDeposits(a.invoiceId(), settles, today, application.getId()));
209	                })
210	                .toList();
211	        audit.record("DEPOSIT_APPLIED id=" + application.getId() + " client=" + clientId
212	                + " amount=" + application.getAmount().toPlainString());
213	        return DepositApplicationResponse.from(application, shares);
214	    }
