217	     * What a share in the client's currency settles on the invoice: the share converted into the invoice's currency
218	     * at the rates in effect on the date. Refused when there is no rate by then or it converts to nothing.
219	     */
220	    private BigDecimal settles(String currency, Invoice invoice, LocalDate date, BigDecimal share) {
221	        BigDecimal settles = fxRates.convert(currency, invoice.getCurrency(), date, share)
222	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
223	                        "No exchange rate for " + invoice.getCurrency() + " on " + date));
224	        if (settles.signum() <= 0) {
225	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
226	                    "The share for invoice #" + invoice.getId() + " is too small to pay anything");
227	        }
228	        return settles;
229	    }
