241	    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
242	        Set<Long> seen = new HashSet<>();
243	        for (A a : allocations) {
244	            if (!seen.add(invoiceId.apply(a))) {
245	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
246	            }
247	        }
