250	    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
251	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
252	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
253	        }
254	        if (invoice.getStatus() == InvoiceStatus.VOID) {
255	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
256	        }
257	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
258	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
259	        }
260	        if (!invoice.getStatus().isOwing()) {
261	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
262	        }
263	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
264	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
265	        BigDecimal settled = paid.add(credited);
266	        if (settled.compareTo(invoice.getAmount()) > 0) {
267	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
268	        }
269	        Payment saved = payments.saveAndFlush(payment.get());
270	        if (invoice.getDueDate() != null && saved.getDate().isBefore(invoice.getDueDate())) {
