328	    public List<CreditNoteResponse> list(Long projectId, Long invoiceId) {
329	        find(projectId, invoiceId);
330	        return creditNotes.findByInvoiceIdOrderByIdAsc(invoiceId).stream().map(CreditNoteResponse::from).toList();
331	    }
332	
333	    /**
334	     * Raises a credit note against an invoice that has been sent to the client and not cancelled. The
335	     * credit notes on an invoice may not add up to more than the invoice amount. The invoice's status is
336	     * then worked out again from what has been paid and credited, so a credit that clears what is left settles it.
337	     */
338	    @Transactional
339	    public CreditNoteResponse issue(Long projectId, Long invoiceId, CreditNoteRequest request) {
340	        Invoice invoice = find(projectId, invoiceId);
341	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before raising a credit note");
343	        }
344	        if (invoice.getStatus() == InvoiceStatus.VOID) {
345	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
346	        }
347	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
348	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
349	        }
350	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId).add(request.amount());
351	        if (credited.compareTo(invoice.getAmount()) > 0) {
352	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Credit is more than the invoice amount");
353	        }
354	        CreditNote saved = creditNotes.saveAndFlush(new CreditNote(invoiceId, request.amount(), clock.instant()));
355	        invoice.applySettledTotals(payments.sumAmountByInvoiceId(invoiceId), credited);
356	        invoices.flush();
357	        audit.record("CREDIT_NOTE_ISSUED invoice=" + invoiceId + " amount=" + saved.getAmount().toPlainString());
358	        return CreditNoteResponse.from(saved);
359	    }
360	
361	    private Invoice find(Long projectId, Long invoiceId) {
362	        return invoices.findById(invoiceId)
363	                .filter(i -> i.getProject().getId().equals(projectId))
364	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
365	    }
366	}
