398	    public List<AdjustmentNoteResponse> list(Long projectId, Long invoiceId) {
399	        find(projectId, invoiceId);
400	        return adjustmentNotes.findByInvoiceIdOrderByIdAsc(invoiceId).stream().map(AdjustmentNoteResponse::from)
401	                .toList();
402	    }
