404	    /**
405	     * Issues an adjustment note against an invoice that has been sent and not cancelled or written off. The
406	     * invoice itself is left exactly as sent; the notes together may not take its adjusted total below zero.
407	     */
408	    @Transactional
409	    public AdjustmentNoteResponse issue(Long projectId, Long invoiceId, AdjustmentNoteRequest request) {
410	        Invoice invoice = find(projectId, invoiceId);
411	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
412	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Edit a draft invoice directly instead");
413	        }
414	        if (invoice.getStatus() == InvoiceStatus.VOID) {
415	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
416	        }
417	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
418	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
419	        }
420	        if (request.amount().signum() == 0) {
421	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An adjustment must change the total");
422	        }
423	        BigDecimal adjusted = invoice.getAmount().add(adjustmentNotes.sumAmountByInvoiceId(invoiceId))
424	                .add(request.amount());
425	        if (adjusted.signum() < 0) {
426	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The adjusted total cannot be below zero");
427	        }
428	        AdjustmentNote saved = adjustmentNotes.saveAndFlush(
429	                new AdjustmentNote(invoiceId, request.amount(), request.reason().strip(), clock.instant()));
430	        audit.record("ADJUSTMENT_NOTE_ISSUED invoice=" + invoiceId + " amount=" + saved.getAmount().toPlainString());
431	        return AdjustmentNoteResponse.from(saved);
432	    }
433	
434	    private Invoice find(Long projectId, Long invoiceId) {
435	        return invoices.findById(invoiceId)
436	                .filter(i -> i.getProject().getId().equals(projectId))
437	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
438	    }
