82	    82	    @Transactional(readOnly = true)
83	    83	    public List<InvoiceResponse> listForProject(Long projectId) {
84	    84	        if (!projects.existsById(projectId)) {
85	    85	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
86	    86	        }
87	    87	        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
88	    88	        Map<Long, BigDecimal> paid = paidByInvoice(found);
89	    89	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
90	    90	        Map<Long, List<Instalment>> schedules = instalments
91	    91	                .findByInvoiceIdIn(found.stream().map(Invoice::getId).toList()).stream()
92	    92	                .collect(Collectors.groupingBy(Instalment::getInvoiceId));
