104	   104	
105	   105	    /**
106	   106	     * How an invoice is keeping to its instalment plan: only an owing invoice with instalments has one. It is BEHIND
107	   107	     * once an unpaid instalment is past its due date, otherwise ON_TRACK.
108	   108	     */
109	   109	    private static ScheduleStatus scheduleStatus(InvoiceStatus status, List<Instalment> schedule, LocalDate today) {
110	   110	        if (!status.isOwing() || schedule.isEmpty()) {
111	   111	            return null;
112	   112	        }
113	   113	        boolean overdue = schedule.stream().anyMatch(n -> !n.isPaid() && n.getDueDate().isBefore(today));
114	   114	        return overdue ? ScheduleStatus.BEHIND : ScheduleStatus.ON_TRACK;
115	   115	    }
