117	   117	    /**
118	   118	     * A client's statement: every invoice across their projects with what is left to pay on each, and
119	   119	     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
120	   120	     * void invoices, as they have been cancelled.
121	   121	     */
122	   122	    @Transactional(readOnly = true)
123	   123	    public ClientStatementResponse statementForClient(Long clientId) {
124	   124	        Client client = clients.findById(clientId)
125	   125	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
126	   126	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
127	   127	        Map<Long, BigDecimal> paid = paidByInvoice(found);
128	   128	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
129	   129	        Function<String, MoneyRule> rules = moneyRules();
130	   130	        List<ClientStatementResponse.Line> lines = found.stream()
131	   131	                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
132	   132	                        credited.getOrDefault(i.getId(), BigDecimal.ZERO), rules.apply(i.getCurrency())))
133	   133	                .toList();
134	   134	        String home = settings.homeCurrency();
135	   135	        MoneyRule homeRule = rules.apply(home);
136	   136	        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines,
137	   137	                accountEntries(clientId, found, rules), home, l -> l.issuedDate() == null ? Optional.empty()
138	   138	                        : fxRates.convert(l.currency(), home, l.issuedDate(), l.amountDue()).map(homeRule::round));
139	   139	    }
