142	   142	     * A client's financial summary as at today: the billed, paid and outstanding totals of their statement, and the
143	   143	     * part of the outstanding left to pay on invoices whose due date has passed.
144	   144	     */
145	   145	    @Transactional(readOnly = true)
146	   146	    public ClientFinancialSummaryResponse financialSummaryForClient(Long clientId) {
