148	   148	        LocalDate today = LocalDate.now(clock);
149	   149	        BigDecimal overdue = statement.invoices().stream()
150	   150	                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
151	   151	                .filter(l -> l.dueDate() != null && l.dueDate().isBefore(today) && l.amountDue().signum() > 0)
152	   152	                .map(ClientStatementResponse.Line::amountDue)
153	   153	                .reduce(BigDecimal.ZERO, BigDecimal::add)
154	   154	                .setScale(2, RoundingMode.HALF_UP);
