175	   175	    /**
176	   176	     * A client's statement for the given date range (both ends included): the balance owed at the start of it, the
177	   177	     * entries dated within it in date order each carrying the running balance, the net movement within it, and the
178	   178	     * balance owed at its end (always the opening balance plus the movements). The payments received within it are
179	   179	     * also listed and totalled on their own, as are the credit notes issued within it.
180	   180	     */
181	   181	    @Transactional(readOnly = true)
182	   182	    public ClientStatementRangeResponse statementForRange(Long clientId, LocalDate from, LocalDate to) {
183	   183	        if (to.isBefore(from)) {
184	   184	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The range must end on or after its start");
185	   185	        }
186	   186	        Client client = clients.findById(clientId)
187	   187	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
188	   188	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
189	   189	        Function<String, MoneyRule> rules = moneyRules();
190	   190	        List<StatementEntry> dated = accountEntries(clientId, found, rules).stream()
191	   191	                .filter(e -> e.date() != null)
192	   192	                .sorted(StatementEntry.DATE_ORDER)
193	   193	                .toList();
194	   194	        BigDecimal opening = dated.stream()
195	   195	                .filter(e -> e.date().isBefore(from))
196	   196	                .map(StatementEntry::change)
197	   197	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
198	   198	        BigDecimal movements = BigDecimal.ZERO.setScale(2);
199	   199	        List<StatementEntry> within = new ArrayList<>();
200	   200	        for (StatementEntry entry : dated) {
201	   201	            if (!entry.date().isBefore(from) && !entry.date().isAfter(to)) {
202	   202	                movements = movements.add(entry.change());
203	   203	                within.add(entry.withBalance(opening.add(movements)));
204	   204	            }
205	   205	        }
206	   206	        List<StatementEntry> paymentsWithin = within.stream()
207	   207	                .filter(e -> e.kind() == StatementEntry.Kind.PAYMENT)
208	   208	                .toList();
209	   209	        BigDecimal paymentsTotal = paymentsWithin.stream()
210	   210	                .map(StatementEntry::credit)
211	   211	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
212	   212	        List<StatementEntry> creditsWithin = within.stream()
213	   213	                .filter(e -> e.kind() == StatementEntry.Kind.CREDIT_NOTE)
214	   214	                .toList();
215	   215	        BigDecimal creditsTotal = creditsWithin.stream()
216	   216	                .map(StatementEntry::credit)
217	   217	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
218	   218	        List<Invoice> issuedByEnd = found.stream()
219	   219	                .filter(i -> i.getIssuedDate() != null && !i.getIssuedDate().isAfter(to))
220	   220	                .toList();
221	   221	        Map<Long, BigDecimal> paidByEnd = new HashMap<>();
222	   222	        Map<Long, BigDecimal> creditedByEnd = new HashMap<>();
223	   223	        List<Long> issuedIds = issuedByEnd.stream().map(Invoice::getId).toList();
224	   224	        if (!issuedIds.isEmpty()) {
225	   225	            payments.findByInvoiceIdIn(issuedIds).stream()
226	   226	                    .filter(p -> p.getDate() == null || !p.getDate().isAfter(to))
227	   227	                    .forEach(p -> paidByEnd.merge(p.getInvoiceId(), p.getAmount(), BigDecimal::add));
228	   228	            creditNotes.findByInvoiceIdIn(issuedIds).stream()
229	   229	                    .filter(n -> !LocalDate.ofInstant(n.getIssuedAt(), ZoneOffset.UTC).isAfter(to))
230	   230	                    .forEach(n -> creditedByEnd.merge(n.getInvoiceId(), n.getAmount(), BigDecimal::add));
231	   231	        }
232	   232	        ClientAgingResponse aging = aging(client, issuedByEnd, paidByEnd, creditedByEnd, rules, to);
233	   233	        return new ClientStatementRangeResponse(client.getId(), client.getCurrency(), from, to, opening, within,
234	   234	                movements, opening.add(movements), paymentsWithin, paymentsTotal, creditsWithin, creditsTotal,
235	   235	                rangeTotal(within, StatementEntry.Kind.INVOICE, StatementEntry::charge),
236	   236	                rangeTotal(within, StatementEntry.Kind.PAYMENT, StatementEntry::credit), aging);
237	   237	    }
238	   238	
239	   239	    /**
240	   240	     * How old a client's debt is as at today: what is left to pay on each owed invoice (not a draft, void or written
241	   241	     * off) counted against how many days past its due date it is.
242	   242	     */
243	   243	    @Transactional(readOnly = true)
244	   244	    public ClientAgingResponse agingForClient(Long clientId) {
245	   245	        Client client = clients.findById(clientId)
246	   246	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
247	   247	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
248	   248	        return aging(client, found, paidByInvoice(found), creditedByInvoice(found), moneyRules(),
249	   249	                LocalDate.now(clock));
250	   250	    }
251	   251	
252	   252	    /**
253	   253	     * What is left to pay on each owed invoice (not a draft, void or written off) given what was paid and credited
254	   254	     * against it, counted against how many days past its due date it is as at the given day.
255	   255	     */
256	   256	    private ClientAgingResponse aging(Client client, List<Invoice> found, Map<Long, BigDecimal> paid,
257	   257	            Map<Long, BigDecimal> credited, Function<String, MoneyRule> rules, LocalDate asOf) {
258	   258	        BigDecimal current = BigDecimal.ZERO.setScale(2);
259	   259	        BigDecimal days30To60 = BigDecimal.ZERO.setScale(2);
260	   260	        BigDecimal days60Plus = BigDecimal.ZERO.setScale(2);
261	   261	        for (Invoice invoice : found) {
262	   262	            BigDecimal invoicePaid = paid.getOrDefault(invoice.getId(), BigDecimal.ZERO);
263	   263	            BigDecimal invoiceCredited = credited.getOrDefault(invoice.getId(), BigDecimal.ZERO);
264	   264	            InvoiceStatus status = invoice.statusFor(invoicePaid, invoiceCredited);
265	   265	            if (status == InvoiceStatus.DRAFT || status.isClosedUnpaid()) {
266	   266	                continue;
267	   267	            }
268	   268	            BigDecimal due = rules.apply(invoice.getCurrency()).round(invoice.amountDue(invoicePaid, invoiceCredited));
269	   269	            if (due.signum() <= 0) {
270	   270	                continue;
271	   271	            }
272	   272	            long overdue = invoice.getDueDate() == null ? 0
273	   273	                    : ChronoUnit.DAYS.between(invoice.getDueDate(), asOf);
274	   274	            if (overdue > 60) {
275	   275	                days60Plus = days60Plus.add(due);
276	   276	            } else if (overdue > 30) {
277	   277	                days30To60 = days30To60.add(due);
278	   278	            } else {
279	   279	                current = current.add(due);
280	   280	            }
281	   281	        }
282	   282	        return new ClientAgingResponse(client.getId(), client.getCurrency(), asOf,
283	   283	                current.setScale(2, RoundingMode.HALF_UP), days30To60.setScale(2, RoundingMode.HALF_UP),
284	   284	                days60Plus.setScale(2, RoundingMode.HALF_UP));
285	   285	    }
286	   286	
287	   287	    /** The total of the given amount over the entries of the given kind. */
288	   288	    private static BigDecimal rangeTotal(List<StatementEntry> entries, StatementEntry.Kind kind,
289	   289	            Function<StatementEntry, BigDecimal> amount) {
290	   290	        return entries.stream()
291	   291	                .filter(e -> e.kind() == kind)
292	   292	                .map(amount)
293	   293	                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
294	   294	    }
295	   295	
296	   296	    /**
297	   297	     * The entries on a client's running account. Drafts have not been sent and void invoices were cancelled, so
298	   298	     * neither is charged. A payment made out of held deposits is left out, as the deposit was already credited
299	   299	     * when it was paid in. Each amount is rounded by the rule of the currency it is in, as the invoice is, so the
300	   300	     * balances add up to the cent.
301	   301	     */
302	   302	    private List<StatementEntry> accountEntries(Long clientId, List<Invoice> found, Function<String, MoneyRule> rules) {
303	   303	        MoneyRule clientRule = clients.findById(clientId).map(c -> rules.apply(c.getCurrency())).orElse(MoneyRule.CENTS);
304	   304	        Map<Long, MoneyRule> invoiceRules = new HashMap<>();
305	   305	        found.forEach(i -> invoiceRules.put(i.getId(), rules.apply(i.getCurrency())));
306	   306	        List<StatementEntry> entries = new ArrayList<>();
307	   307	        List<Long> sent = new ArrayList<>();
308	   308	        Map<Long, String> poNumbers = new HashMap<>();
309	   309	        for (Invoice invoice : found) {
310	   310	            if (invoice.getStatus() == InvoiceStatus.DRAFT) {
311	   311	                continue;
312	   312	            }
313	   313	            sent.add(invoice.getId());
314	   314	            if (invoice.getPoNumber() != null) {
315	   315	                poNumbers.put(invoice.getId(), invoice.getPoNumber());
316	   316	            }
317	   317	            if (invoice.getStatus() != InvoiceStatus.VOID) {
318	   318	                entries.add(StatementEntry.charge(StatementEntry.Kind.INVOICE, invoice.getId(), invoice.getId(),
319	   319	                        invoice.getIssuedDate(), "Invoice #" + invoice.getId(), invoiceRules.get(invoice.getId()).round(invoice.getAmount()),
320	   320	                        invoice.getPoNumber()));
321	   321	            }
322	   322	        }
323	   323	        if (!sent.isEmpty()) {
324	   324	            for (Payment payment : payments.findByInvoiceIdIn(sent)) {
325	   325	                if (payment.getDepositApplicationId() == null) {
326	   326	                    entries.add(StatementEntry.credit(StatementEntry.Kind.PAYMENT, payment.getId(), payment.getInvoiceId(),
327	   327	                            payment.getDate(), "Payment on invoice #" + payment.getInvoiceId(),
328	   328	                            invoiceRules.get(payment.getInvoiceId()).round(payment.getAmount()),
329	   329	                            poNumbers.get(payment.getInvoiceId())));
330	   330	                }
331	   331	            }
332	   332	            for (CreditNote note : creditNotes.findByInvoiceIdIn(sent)) {
333	   333	                entries.add(StatementEntry.credit(StatementEntry.Kind.CREDIT_NOTE, note.getId(), note.getInvoiceId(),
334	   334	                        LocalDate.ofInstant(note.getIssuedAt(), ZoneOffset.UTC),
335	   335	                        "Credit note on invoice #" + note.getInvoiceId(),
336	   336	                        invoiceRules.get(note.getInvoiceId()).round(note.getAmount()),
337	   337	                        poNumbers.get(note.getInvoiceId())));
338	   338	            }
339	   339	        }
340	   340	        for (Deposit deposit : deposits.findByClientIdOrderByDateAscIdAsc(clientId)) {
341	   341	            entries.add(StatementEntry.credit(StatementEntry.Kind.DEPOSIT, deposit.getId(), null, deposit.getDate(),
342	   342	                    "Deposit", clientRule.round(deposit.getAmount()), null));
343	   343	        }
344	   344	        for (Refund refund : refunds.findByClientIdOrderByDateDescIdDesc(clientId)) {
