383	   383	    @Transactional
384	   384	    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
385	   385	        Project project = projects.findById(projectId)
386	   386	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
387	   387	        if (project.isClosed()) {
388	   388	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The job is closed; no new invoice can be raised on it");
389	   389	        }
390	   390	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
391	   391	        // Without a due date the invoice falls due after the client's payment terms (net N days).
392	   392	        LocalDate due = request.dueDate() != null ? request.dueDate()
393	   393	                : issued.plusDays(InvoiceRequest.termDays(project.getClient().getPaymentTermsDays()));
394	   394	        if (due.isBefore(issued)) {
395	   395	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
396	   396	        }
397	   397	        Invoice invoice = new Invoice(project, issued, due);
398	   398	        if (request.amount() != null) {
399	   399	            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, null, request.amount());
400	   400	        }
401	   401	        invoice.applyTax(request.taxPct() != null ? request.taxPct() : settings.defaultTaxPct());
402	   402	        // A new invoice starts with the client's standard discount, if they have one.
403	   403	        BigDecimal defaultDiscountPct = project.getClient().getDefaultDiscountPct();
404	   404	        if (defaultDiscountPct.signum() > 0) {
405	   405	            invoice.applyDiscount(defaultDiscountPct);
406	   406	        }
407	   407	        Invoice saved = invoices.save(invoice);
408	   408	        return InvoiceResponse.from(saved, BigDecimal.ZERO, BigDecimal.ZERO);
409	   409	    }
