558	   558	    /**
559	   559	     * Sends a draft invoice and records the sending in the audit log. An invoice that would take the
560	   560	     * client over their credit limit is refused and stays a draft.
561	   561	     */
562	   562	    @Transactional
563	   563	    public InvoiceResponse send(Long projectId, Long invoiceId) {
564	   564	        Invoice invoice = find(projectId, invoiceId);
565	   565	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
566	   566	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
567	   567	        }
568	   568	        if (invoice.getAmount().signum() == 0) {
569	   569	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
570	   570	        }
571	   571	        Client client = invoice.getProject().getClient();
572	   572	        BigDecimal limit = client.getCreditLimit();
573	   573	        if (limit != null && clientService.outstanding(client.getId()).add(invoice.getAmount()).compareTo(limit) > 0) {
574	   574	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
575	   575	                    "Sending this invoice would take the client over their credit limit");
576	   576	        }
577	   577	        invoice.markSent(LocalDate.now(clock));
578	   578	        invoices.flush();
579	   579	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
580	   580	        return toResponse(invoice);
581	   581	    }
