583	   583	    /**
584	   584	     * Sends every draft invoice on a job in one go, and records each sending in the audit log. It is all or
585	   585	     * nothing: if any draft has no line items, or sending them all would take the client over their credit
586	   586	     * limit, none are sent.
587	   587	     */
588	   588	    @Transactional
589	   589	    public List<InvoiceResponse> sendDrafts(Long projectId) {
590	   590	        if (!projects.existsById(projectId)) {
591	   591	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
592	   592	        }
593	   593	        List<Invoice> drafts = invoices.findByProjectIdOrderById(projectId).stream()
594	   594	                .filter(i -> i.getStatus() == InvoiceStatus.DRAFT)
595	   595	                .toList();
596	   596	        if (drafts.isEmpty()) {
597	   597	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There are no draft invoices to send");
598	   598	        }
599	   599	        if (drafts.stream().anyMatch(i -> i.getAmount().signum() == 0)) {
600	   600	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item to every draft before sending");
601	   601	        }
602	   602	        Client client = drafts.get(0).getProject().getClient();
603	   603	        BigDecimal limit = client.getCreditLimit();
604	   604	        BigDecimal total = drafts.stream().map(Invoice::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
605	   605	        if (limit != null && clientService.outstanding(client.getId()).add(total).compareTo(limit) > 0) {
606	   606	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
607	   607	                    "Sending these invoices would take the client over their credit limit");
608	   608	        }
609	   609	        LocalDate today = LocalDate.now(clock);
610	   610	        drafts.forEach(i -> i.markSent(today));
611	   611	        invoices.flush();
612	   612	        drafts.forEach(i -> audit.record("INVOICE_SENT id=" + i.getId() + " amount=" + i.getAmount().toPlainString()));
613	   613	        return drafts.stream().map(this::toResponse).toList();
614	   614	    }
