651	   651	    /**
652	   652	     * Writes off a sent or part-paid invoice as bad debt, so what is left on it no longer counts toward what is
653	   653	     * owed while the invoice stays on record, and records the write-off (the balance given up) in the audit log.
654	   654	     */
655	   655	    @Transactional
656	   656	    public InvoiceDetailResponse writeOff(Long projectId, Long invoiceId) {
657	   657	        Invoice invoice = find(projectId, invoiceId);
658	   658	        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId);
659	   659	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId);
660	   660	        if (!invoice.statusFor(paid, credited).isOwing()) {
661	   661	            throw new ResponseStatusException(HttpStatus.CONFLICT,
662	   662	                    "Only a sent invoice with something still owed can be written off");
663	   663	        }
664	   664	        BigDecimal balance = invoice.amountDue(paid, credited);
665	   665	        invoice.markWrittenOff();
666	   666	        invoices.flush();
667	   667	        audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + balance.setScale(2).toPlainString());
668	   668	        return detail(invoice);
669	   669	    }
670	   670	
671	   671	    /**
672	   672	     * Writes off part of a sent or part-paid invoice as bad debt, so that part no longer counts toward what is
673	   673	     * owed while the rest still does, and records the part given up in the audit log. The invoice's status is then
674	   674	     * worked out from what is still owed after the write-off. Writing off everything still owed writes off the
675	   675	     * whole invoice.
676	   676	     */
677	   677	    @Transactional
678	   678	    public InvoiceDetailResponse writeOffPart(Long projectId, Long invoiceId, PartialWriteOffRequest request) {
679	   679	        Invoice invoice = find(projectId, invoiceId);
680	   680	        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId);
681	   681	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoiceId);
682	   682	        if (!invoice.statusFor(paid, credited).isOwing()) {
683	   683	            throw new ResponseStatusException(HttpStatus.CONFLICT,
684	   684	                    "Only a sent invoice with something still owed can be written off");
685	   685	        }
686	   686	        BigDecimal balance = invoice.amountDue(paid, credited);
687	   687	        int comparison = request.amount().compareTo(balance);
688	   688	        if (comparison > 0) {
689	   689	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
690	   690	                    "Cannot write off more than is still owed");
691	   691	        }
692	   692	        if (comparison == 0) {
693	   693	            return writeOff(projectId, invoiceId);
694	   694	        }
695	   695	        invoice.writeOffPart(request.amount());
696	   696	        invoice.applySettledTotals(paid, credited);
697	   697	        invoices.flush();
698	   698	        audit.record("INVOICE_PART_WRITTEN_OFF id=" + invoice.getId() + " amount="
699	   699	                + request.amount().setScale(2).toPlainString());
700	   700	        return detail(invoice);
701	   701	    }
