731	   731	    /**
732	   732	     * The invoice in full; a foreign invoice also converted into the home currency at the exchange rate
733	   733	     * from its issue date, so a later rate never changes what it was worth.
734	   734	     */
735	   735	    private InvoiceDetailResponse detail(Invoice invoice, InvoiceStatus status) {
736	   736	        String home = settings.homeCurrency();
737	   737	        String currency = invoice.getCurrency();
738	   738	        BigDecimal homeAmount = currency.equals(home) ? null
739	   739	                : fxRates.toHome(currency, invoice.getIssuedDate(), invoice.getAmount()).orElse(null);
740	   740	        BigDecimal amountDue = invoice.dueNow(payments.sumAmountByInvoiceId(invoice.getId()),
741	   741	                creditNotes.sumAmountByInvoiceId(invoice.getId()));
742	   742	        BigDecimal fxGainLoss = currency.equals(home) ? null : fxGainLoss(invoice, currency);
743	   743	        return InvoiceDetailResponse.from(invoice, status, home, homeAmount, LocalDate.now(clock), amountDue, fxGainLoss);
744	   744	    }
745	   745	
746	   746	    /**
747	   747	     * The exchange gain (positive) or loss (negative) in the home currency realised by the payments on a foreign
748	   748	     * invoice: each payment's amount is worth its value at the rate on the payment's date less its value at the
749	   749	     * rate on the invoice's issue date. Null when there are no payments or a rate is missing.
750	   750	     */
751	   751	    private BigDecimal fxGainLoss(Invoice invoice, String currency) {
752	   752	        List<Payment> paid = payments.findByInvoiceIdOrderByDateAscIdAsc(invoice.getId());
753	   753	        if (paid.isEmpty() || invoice.getIssuedDate() == null) {
754	   754	            return null;
755	   755	        }
756	   756	        BigDecimal total = BigDecimal.ZERO;
757	   757	        for (Payment payment : paid) {
758	   758	            Optional<BigDecimal> atIssue = fxRates.toHome(currency, invoice.getIssuedDate(), payment.getAmount());
759	   759	            Optional<BigDecimal> atPayment = fxRates.toHome(currency, payment.getDate(), payment.getAmount());
760	   760	            if (atIssue.isEmpty() || atPayment.isEmpty()) {
761	   761	                return null;
762	   762	            }
763	   763	            total = total.add(atPayment.get().subtract(atIssue.get()));
764	   764	        }
765	   765	        return total;
766	   766	    }
