 82	    @Transactional(readOnly = true)
 83	    public List<InvoiceResponse> listForProject(Long projectId) {
 84	        if (!projects.existsById(projectId)) {
 85	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job");
 86	        }
 87	        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
 88	        Map<Long, BigDecimal> paid = paidByInvoice(found);
 89	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
 90	        Map<Long, List<Instalment>> schedules = instalments
 91	                .findByInvoiceIdIn(found.stream().map(Invoice::getId).toList()).stream()
 92	                .collect(Collectors.groupingBy(Instalment::getInvoiceId));
 93	        LocalDate today = LocalDate.now(clock);
 94	        return found.stream()
 95	                .map(i -> {
 96	                    BigDecimal invoicePaid = paid.getOrDefault(i.getId(), BigDecimal.ZERO);
 97	                    BigDecimal invoiceCredited = credited.getOrDefault(i.getId(), BigDecimal.ZERO);
 98	                    ScheduleStatus schedule = scheduleStatus(i.statusFor(invoicePaid, invoiceCredited),
 99	                            schedules.getOrDefault(i.getId(), List.of()), today);
100	                    return InvoiceResponse.from(i, invoicePaid, invoiceCredited, schedule);
101	                })
102	                .toList();
103	    }
104	
105	    /**
106	     * How an invoice is keeping to its instalment plan: only an owing invoice with instalments has one. It is BEHIND
107	     * once an unpaid instalment is past its due date, otherwise ON_TRACK.
108	     */
109	    private static ScheduleStatus scheduleStatus(InvoiceStatus status, List<Instalment> schedule, LocalDate today) {
110	        if (!status.isOwing() || schedule.isEmpty()) {
111	            return null;
112	        }
113	        boolean overdue = schedule.stream().anyMatch(n -> !n.isPaid() && n.getDueDate().isBefore(today));
114	        return overdue ? ScheduleStatus.BEHIND : ScheduleStatus.ON_TRACK;
115	    }
116	
117	    /**
118	     * A client's statement: every invoice across their projects with what is left to pay on each, and
119	     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
120	     * void invoices, as they have been cancelled.
121	     */
122	    @Transactional(readOnly = true)
123	    public ClientStatementResponse statementForClient(Long clientId) {
124	        Client client = clients.findById(clientId)
125	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
126	        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
127	        Map<Long, BigDecimal> paid = paidByInvoice(found);
128	        Map<Long, BigDecimal> credited = creditedByInvoice(found);
129	        Function<String, MoneyRule> rules = moneyRules();
130	        List<ClientStatementResponse.Line> lines = found.stream()
131	                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
132	                        credited.getOrDefault(i.getId(), BigDecimal.ZERO), rules.apply(i.getCurrency())))
133	                .toList();
134	        String home = settings.homeCurrency();
135	        MoneyRule homeRule = rules.apply(home);
136	        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines,
137	                accountEntries(clientId, found, rules), home, l -> l.issuedDate() == null ? Optional.empty()
138	                        : fxRates.convert(l.currency(), home, l.issuedDate(), l.amountDue()).map(homeRule::round));
139	    }
140	
141	    /**
142	     * A client's financial summary as at today: the billed, paid and outstanding totals of their statement, and the
143	     * part of the outstanding left to pay on invoices whose due date has passed.
144	     */
145	    @Transactional(readOnly = true)
146	    public ClientFinancialSummaryResponse financialSummaryForClient(Long clientId) {
147	        ClientStatementResponse statement = statementForClient(clientId);
148	        LocalDate today = LocalDate.now(clock);
149	        BigDecimal overdue = statement.invoices().stream()
150	                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
151	                .filter(l -> l.dueDate() != null && l.dueDate().isBefore(today) && l.amountDue().signum() > 0)
152	                .map(ClientStatementResponse.Line::amountDue)
153	                .reduce(BigDecimal.ZERO, BigDecimal::add)
154	                .setScale(2, RoundingMode.HALF_UP);
155	        return new ClientFinancialSummaryResponse(statement.clientId(), statement.currency(), today,
156	                statement.invoiced(), statement.paid(), statement.outstanding(), overdue);
157	    }
