351	    /** Looks up each currency's rounding rule once per request. */
352	    private Function<String, MoneyRule> moneyRules() {
353	        Map<String, MoneyRule> known = new HashMap<>();
354	        return code -> known.computeIfAbsent(code, currencies::ruleFor);
355	    }
