357	    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
358	        return found.isEmpty() ? Map.of()
359	                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
360	                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
