    31	        this.currencies = currencies;
    32	        this.settings = settings;
    33	        this.audit = audit;
    34	    }
    35	
    36	    /** The recorded rates, by currency with the most recent first. */
    37	    @Transactional(readOnly = true)
    38	    public List<FxRateResponse> list() {
    39	        return rates.findAllByOrderByCurrencyAscRateDateDescIdDesc().stream().map(FxRateResponse::from).toList();
    40	    }
    41	
    42	    /**
    43	     * Records the currency's rate from the date, recording it in the audit log. A currency has at most one
    44	     * rate a day, and the home currency needs none.
    45	     */
    46	    @Transactional
    47	    public FxRateResponse record(FxRateRequest request) {
    48	        String currency = request.currency().trim().toUpperCase(Locale.ROOT);
    49	        if (!currencies.exists(currency)) {
    50	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
    51	        }
    52	        if (currency.equals(settings.homeCurrency())) {
    53	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The home currency needs no exchange rate");
    54	        }
    55	        if (rates.existsByCurrencyAndRateDate(currency, request.date())) {
    56	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rate for this currency on this date already exists");
    57	        }
    58	        FxRate saved = rates.saveAndFlush(new FxRate(currency, request.date(), request.rate()));
    59	        audit.record("FX_RATE_RECORDED id=" + saved.getId() + " currency=" + currency + " date=" + saved.getRateDate()
    60	                + " rate=" + saved.getRate().stripTrailingZeros().toPlainString());
    61	        return FxRateResponse.from(saved);
    62	    }
    63	
    64	    /**
    65	     * The amount in the home currency, converted at the currency's rate on the date (its latest rate dated
    66	     * on or before it); empty when the currency has no rate by then.
    67	     */
    68	    @Transactional(readOnly = true)
    69	    public Optional<BigDecimal> toHome(String currency, LocalDate date, BigDecimal amount) {
    70	        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date)
    71	                .map(r -> amount.multiply(r.getRate()).setScale(2, RoundingMode.HALF_UP));
    72	    }
    73	
