    75	     * The amount converted from one currency into another at the rates in effect on the date, going through the
    76	     * home currency; empty when either foreign currency has no rate by then. The same currency converts as is.
    77	     */
    78	    @Transactional(readOnly = true)
    79	    public Optional<BigDecimal> convert(String from, String to, LocalDate date, BigDecimal amount) {
    80	        if (from.equals(to)) {
    81	            return Optional.of(amount.setScale(2, RoundingMode.HALF_UP));
    82	        }
    83	        Optional<BigDecimal> fromRate = rateToHome(from, date);
    84	        Optional<BigDecimal> toRate = rateToHome(to, date);
    85	        if (fromRate.isEmpty() || toRate.isEmpty()) {
    86	            return Optional.empty();
    87	        }
    88	        return Optional.of(amount.multiply(fromRate.get()).divide(toRate.get(), 2, RoundingMode.HALF_UP));
    89	    }
    90	
    91	    /** How many units of the home currency one unit of the currency is worth on the date. */
    92	    private Optional<BigDecimal> rateToHome(String currency, LocalDate date) {
    93	        if (currency.equals(settings.homeCurrency())) {
    94	            return Optional.of(BigDecimal.ONE);
    95	        }
    96	        return rates.findFirstByCurrencyAndRateDateLessThanEqualOrderByRateDateDesc(currency, date).map(FxRate::getRate);
    97	    }
    98	}

